from collections import deque

def topological_order(graph):
    indegree = {}
    for vertex in graph:
        indegree[vertex] = 0
    for vertex in graph:
        for neighbor in graph[vertex]:
            indegree[neighbor] += 1
    ready = deque()
    for vertex in graph:
        if indegree[vertex] == 0:
            ready.append(vertex)
    order = []
    while ready:
        vertex = ready.popleft()
        order.append(vertex)
        for neighbor in graph[vertex]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                ready.append(neighbor)
    if len(order) != len(graph):
        return None
    return order

graph = {"A": ["C"], "B": ["C"], "C": [], "D": []}
print(topological_order(graph))
print(topological_order({"A": ["B"], "B": ["A"]}))
print(topological_order({}))

